using System.Collections;
using UnityEngine;
using Oathx.Core;

/// <summary>
/// runtime logic system
/// </summary>
public abstract class RuntimeSystem : XEventModule
{
    /// <summary>
    /// load system
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    public virtual void LoadSystem(System.Type type, System.Action complete=null)
    {
        XCoroutine.Run(DoLoadAsync(type, complete));
    }

    /// <summary>
    /// do load async
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    /// <returns></returns>
    private IEnumerator DoLoadAsync(System.Type type, System.Action complete)
    {
        var module = dispatcher.Load(type);
        if (module != null && !module.IsActive())
            module.Active();

        yield return new WaitForEndOfFrame();

        complete?.Invoke();
    }

    /// <summary>
    /// unload system
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    public void UnloadSystem(System.Type type, System.Action complete)
    {
        XCoroutine.Run(DoUnloadAsync(type, complete));
    }

    /// <summary>
    /// do unload async
    /// </summary>
    /// <param name="type"></param>
    /// <param name="complete"></param>
    /// <returns></returns>
    IEnumerator DoUnloadAsync(System.Type type, System.Action complete)
    {
        dispatcher.Unload(type);
        yield return new WaitForEndOfFrame();
        complete?.Invoke();
    }
}

using Oathx.Core;
using Oathx.Entity;
using System.Collections;

/// <summary>
/// Requests system loading and activation through MasterSystem.
/// </summary>
public class SystemActive : IEvent
{
    /// <summary>
    /// Runtime system type to activate.
    /// </summary>
    public System.Type type { get; set; }

    /// <summary>
    /// Optional action after the system activation step completes.
    /// </summary>
    public System.Action complete { get; set; }
}

/// <summary>
/// Requests system deactivation and unloading through MasterSystem.
/// </summary>
public class SystemDetive : IEvent
{
    /// <summary>
    /// Runtime system type to unload.
    /// </summary>
    public System.Type type { get; set; }

    /// <summary>
    /// Optional action after the system unloading step completes.
    /// </summary>
    public System.Action complete { get; set; }
}

/// <summary>
/// Local login success notification that permits game startup.
/// </summary>
public class LoginSucceed : IEvent
{
    /// <summary>
    /// Player identifier supplied by the local caller.
    /// </summary>
    public int pid 
    { get; set; }
}

/// <summary>
/// Local login failure notification.
/// </summary>
public class LoginFailure : IEvent
{
    /// <summary>
    /// Player identifier supplied by the local caller.
    /// </summary>
    public int code
    { get; set; }
}

/// <summary>
/// Coordinates local player persistence and business system startup.
/// </summary>
public class MasterSystem : RuntimeSystem
{
    /// <summary>
    /// Subscribe to local login success without starting Home.
    /// </summary>
    /// <returns>True after registering the local login handler.</returns>
    public override bool OnActive()
    {
        Subscribe<LoginSucceed>(OnLoginSucceed);
        Subscribe<SystemActive>(OnSystemActive);
        Subscribe<SystemDetive>(OnSystemDetive);
        Subscribe<HomeEntryRequested>(OnHomeEntryRequested);
        Subscribe<FunctionOpenChanged>(OnFunctionChanged);

        return true;
    }

    /// <summary>
    /// Release local event subscriptions and unload Home.
    /// </summary>
    public override void OnDetive()
    {
        UnsubscribeAll();

        Unload();
    }

    /// <summary>
    /// Restore local data or persist initial values before starting business systems.
    /// </summary>
    /// <returns>True when local player data is ready.</returns>
    public bool Load()
    {
        if (!IsActive())
            return false;

        if (!XEntityManager.GetSingleton().TryGetEntity(nameof(MasterEntity), out var entity)
            || !(entity is MasterEntity master))
            return false;

        bool ready = master.ExistsSerializeFile()
            ? master.Deserialize()
            : !string.IsNullOrEmpty(master.Serialize());
        if (!ready)
            return false;

        return true;
    }

    /// <summary>
    /// Unload Home, including during deactivation.
    /// </summary>
    /// <returns>True after requesting Home removal from the dispatcher.</returns>
    public bool Unload()
    {
        dispatcher.Unload(typeof(MailSystem));
        dispatcher.Unload(typeof(ShopSystem));
        dispatcher.Unload(typeof(NoticeSystem));
        dispatcher.Unload(typeof(FightSystem));
        dispatcher.Unload(typeof(HomeSystem));

        return true;
    }

    /// <summary>
    /// Persist the current local player data without contacting a server.
    /// </summary>
    /// <returns>True when the local archive has been written.</returns>
    public bool Save()
    {
        if (!IsActive())
            return false;

        if (!XEntityManager.GetSingleton().TryGetEntity(nameof(MasterEntity), out var entity)
            || !(entity is MasterEntity master))
            return false;

        return !string.IsNullOrEmpty(master.Serialize());
    }

    /// <summary>
    /// Load and activate a requested business system.
    /// </summary>
    /// <param name="data">Target system and optional completion action.</param>
    private void OnSystemActive(SystemActive data)
    {
        if (IsActive() && IsSystemType(data.type) && FunctionManagerAccess.CanActivate(data.type))
            XCoroutine.Run(ActivateSystem(data));
    }

    /// <summary>Route the reference Home mall entry through the system coordinator.</summary>
    /// <param name="data">Home navigation request.</param>
    private void OnHomeEntryRequested(HomeEntryRequested data)
    {
        if (IsActive() && data.entry == HomeEntry.Shop)
            OnSystemActive(new SystemActive { type = typeof(ShopSystem) });

        if (IsActive() && data.entry == HomeEntry.Mail)
            OnSystemActive(new SystemActive { type = typeof(MailSystem) });
    }

    /// <summary>
    /// Wait until event dispatch has finished before changing the system registry.
    /// </summary>
    /// <param name="data">Target system and optional completion action.</param>
    /// <returns>The deferred activation sequence.</returns>
    private IEnumerator ActivateSystem(SystemActive data)
    {
        yield return null;

        if (IsActive() && FunctionManagerAccess.CanActivate(data.type))
            LoadSystem(data.type, data.complete);
    }

    /// <summary>
    /// Unload a requested business system and its dependent pages.
    /// </summary>
    /// <param name="data">Target system and optional completion action.</param>
    private void OnSystemDetive(SystemDetive data)
    {
        if (IsActive() && IsSystemType(data.type))
        {
            if (data.type == typeof(LoginSystem))
                dispatcher.Unload(typeof(NoticeSystem));

            UnloadSystem(data.type, data.complete);
        }
    }

    /// <summary>Close a business system when its configured gate becomes unavailable.</summary>
    /// <param name="data">Calculated availability transition.</param>
    private void OnFunctionChanged(FunctionOpenChanged data)
    {
        if (!data.opened && Config.Excel.functionSystemConfig.TryGetValue(data.id, out var row))
        {
            var type = FunctionManagerAccess.ResolveType(row);
            if (IsSystemType(type) && type != typeof(FunctionManagerSystem) && type != typeof(RedDotSystem))
                XCoroutine.Run(CloseUnavailable(type));
        }
    }

    /// <summary>Defer registry changes and reject stale close messages.</summary>
    /// <param name="type">Business system to close.</param>
    /// <returns>The deferred close sequence.</returns>
    private IEnumerator CloseUnavailable(System.Type type)
    {
        yield return null;

        if (IsActive() && !FunctionManagerAccess.CanActivate(type))
            UnloadSystem(type, null);
    }

    /// <summary>
    /// Reject invalid targets and requests to replace the lifecycle coordinator.
    /// </summary>
    /// <param name="type">Requested system type.</param>
    /// <returns>True for a concrete business runtime system.</returns>
    private bool IsSystemType(System.Type type)
    {
        return type != null && type != typeof(MasterSystem) && !type.IsAbstract
            && typeof(RuntimeSystem).IsAssignableFrom(type);
    }

    /// <summary>
    /// Prepare local player data and start Home after local login succeeds.
    /// </summary>
    /// <param name="data">Local login success notification.</param>
    private void OnLoginSucceed(LoginSucceed data)
    {
        if (Load())
        {
            Launch();
        }
    }

    /// <summary>
    /// Unload login and request Home startup.
    /// </summary>
    /// <returns>True when the transition has been requested.</returns>
    private bool Launch()
    {
        if (!IsActive())
            return false;

        dispatcher.Unload(typeof(NoticeSystem));

        UnloadSystem(typeof(LoginSystem), () => {
            if (IsActive())
            {
                LoadSystem(typeof(HomeSystem));
            }
        });

        return true;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Oathx.Entity;

/// <summary>Owns local inbox state and validates every mail operation.</summary>
[Initialize]
public partial class MailEntity : XEntity
{
    /// <summary>Private inbox, detached from caller-owned records.</summary>
    private readonly List<MailMessage> messages = new List<MailMessage>();

    /// <summary>Local claim receipts; these are not inventory grants.</summary>
    private readonly List<MailMessage> receipts = new List<MailMessage>();

    /// <summary>Whether the host has supplied an inbox, including an empty inbox.</summary>
    public bool initialized
    { get; private set; }

    /// <summary>Selected message identifier, or zero when nothing is selected.</summary>
    public int selectedId
    { get; private set; }

    /// <summary>Atomically replace the inbox after validating and copying all records.</summary>
    /// <param name="source">Host records to copy.</param>
    /// <returns>True when every record is valid.</returns>
    public bool ReplaceInbox(IEnumerable<MailMessage> source)
    {
        if (source == null)
            return false;

        var copy = new List<MailMessage>();
        var ids = new HashSet<int>();
        foreach (var message in source)
        {
            if (message == null || message.id <= 0 || !ids.Add(message.id)
                || message.title == null || message.body == null || message.rewards == null
                || message.sentAt < 0 || message.expiresAt > 253402300799L || message.expiresAt <= message.sentAt
                || message.rewards.Any(item => item == null || item.itemId <= 0 || item.count <= 0 || string.IsNullOrEmpty(item.icon)))
                return false;

            var itemCopy = Copy(message);
            if (receipts.Any(item => item.id == message.id))
                itemCopy.claimed = true;

            copy.Add(itemCopy);
        }

        messages.Clear();
        messages.AddRange(copy);
        initialized = true;
        selectedId = 0;

        return true;
    }

    /// <summary>Read detached, unexpired records in stable newest-first order.</summary>
    /// <param name="now">Current UTC Unix seconds.</param>
    /// <returns>A detached inbox snapshot.</returns>
    public List<MailMessage> GetMessages(long now)
    {
        return messages.Where(item => item.expiresAt > now).OrderByDescending(item => item.sentAt)
            .ThenByDescending(item => item.id).Select(Copy).ToList();
    }

    /// <summary>Read the selected, unexpired message.</summary>
    /// <param name="now">Current UTC Unix seconds.</param>
    /// <returns>A detached record or null.</returns>
    public MailMessage GetSelected(long now)
    {
        var message = messages.Find(item => item.id == selectedId && item.expiresAt > now);

        return message == null ? null : Copy(message);
    }

    /// <summary>Select a live message and mark it read.</summary>
    /// <param name="id">Message identifier.</param>
    /// <param name="now">Current UTC Unix seconds.</param>
    /// <returns>True when the record is available.</returns>
    public bool Select(int id, long now)
    {
        var message = messages.Find(item => item.id == id && item.expiresAt > now);
        if (message == null)
            return false;

        selectedId = id;
        message.read = true;

        return true;
    }

    /// <summary>Check current eligibility for a claim.</summary>
    /// <param name="id">Message identifier.</param>
    /// <param name="now">Current UTC Unix seconds.</param>
    /// <returns>The business result without mutating state.</returns>
    public MailResult CheckClaim(int id, long now)
    {
        var message = messages.Find(item => item.id == id);
        if (message == null)
            return MailResult.NotFound;

        if (message.expiresAt <= now)
            return MailResult.Expired;

        if (message.claimed)
            return MailResult.AlreadyClaimed;

        return message.rewards.Count == 0 ? MailResult.NoAttachment : MailResult.Success;
    }

    /// <summary>Check deletion eligibility from current owned data.</summary>
    /// <param name="id">Message identifier.</param>
    /// <returns>The business result without mutating state.</returns>
    public MailResult CheckDelete(int id)
    {
        var message = messages.Find(item => item.id == id);
        if (message == null)
            return MailResult.NotFound;

        if (!message.read)
            return MailResult.Unread;

        return !message.claimed && message.rewards.Count > 0 ? MailResult.PendingAttachments : MailResult.Success;
    }

    /// <summary>Record a local claim exactly once without granting inventory.</summary>
    /// <param name="id">Message identifier.</param>
    /// <param name="now">Current UTC Unix seconds.</param>
    /// <returns>The validated operation result.</returns>
    public MailResult Claim(int id, long now)
    {
        var result = CheckClaim(id, now);
        if (result != MailResult.Success)
            return result;

        var message = messages.Find(item => item.id == id);
        message.read = true;
        message.claimed = true;

        receipts.Add(Copy(message));

        return MailResult.Success;
    }

    /// <summary>Delete only read records without outstanding attachments.</summary>
    /// <param name="id">Message identifier.</param>
    /// <returns>The validated operation result.</returns>
    public MailResult Delete(int id)
    {
        var result = CheckDelete(id);
        if (result != MailResult.Success)
            return result;

        var message = messages.Find(item => item.id == id);
        messages.Remove(message);
        if (selectedId == id)
            selectedId = 0;

        return MailResult.Success;
    }

    /// <summary>Claim all eligible messages using the same per-record validation.</summary>
    /// <param name="now">Current UTC Unix seconds.</param>
    /// <returns>The number of newly recorded claims.</returns>
    public int ClaimAll(long now)
    {
        int count = 0;
        foreach (var message in GetMessages(now))
        {
            if (Claim(message.id, now) == MailResult.Success)
                count++;
        }

        return count;
    }

    /// <summary>Delete eligible read messages while preserving unread and pending mail.</summary>
    /// <returns>The number of removed messages.</returns>
    public int DeleteRead()
    {
        int count = 0;
        foreach (int id in messages.Select(item => item.id).ToArray())
        {
            if (Delete(id) == MailResult.Success)
                count++;
        }

        return count;
    }

    /// <summary>Read detached local receipts for host integration or verification.</summary>
    /// <returns>Local receipts without inventory side effects.</returns>
    public List<MailMessage> GetReceipts()
    {
        return receipts.Select(Copy).ToList();
    }

    /// <summary>Copy a record and every mutable attachment.</summary>
    /// <param name="source">Validated source record.</param>
    /// <returns>A detached record.</returns>
    private static MailMessage Copy(MailMessage source)
    {
        return new MailMessage {
            id = source.id, title = source.title, body = source.body,
            sentAt = source.sentAt, expiresAt = source.expiresAt,
            read = source.read, claimed = source.claimed,
            rewards = source.rewards.Select(item => new MailReward {
                itemId = item.itemId, count = item.count, icon = item.icon
            }).ToList()
        };
    }
}

/// <summary>Detached host-supplied mail data.</summary>
public class MailMessage
{
    /// <summary>Stable positive mail identifier.</summary>
    public int id
    { get; set; }

    /// <summary>Dynamic subject supplied by the product.</summary>
    public string title
    { get; set; }

    /// <summary>Dynamic message body supplied by the product.</summary>
    public string body
    { get; set; }

    /// <summary>UTC send time in Unix seconds.</summary>
    public long sentAt
    { get; set; }

    /// <summary>UTC expiry time in Unix seconds.</summary>
    public long expiresAt
    { get; set; }

    /// <summary>Whether the message has been read.</summary>
    public bool read
    { get; set; }

    /// <summary>Whether attachment collection has been recorded.</summary>
    public bool claimed
    { get; set; }

    /// <summary>Detached attachment data.</summary>
    public List<MailReward> rewards
    { get; set; } = new List<MailReward>();
}

/// <summary>Detached attachment description, not an inventory item.</summary>
public class MailReward
{
    /// <summary>Product item identifier.</summary>
    public int itemId
    { get; set; }

    /// <summary>Positive attachment quantity.</summary>
    public int count
    { get; set; }

    /// <summary>Product icon asset path.</summary>
    public string icon
    { get; set; }
}

/// <summary>Business results independent of display language.</summary>
public enum MailResult
{
    /// <summary>The operation completed.</summary>
    Success,

    /// <summary>The requested record is absent.</summary>
    NotFound,

    /// <summary>The record has expired.</summary>
    Expired,

    /// <summary>A claim was already recorded.</summary>
    AlreadyClaimed,

    /// <summary>The record has no attachments.</summary>
    NoAttachment,

    /// <summary>The record has not been read.</summary>
    Unread,

    /// <summary>Attachments must be claimed before deletion.</summary>
    PendingAttachments
}

using System;
using System.Globalization;
using System.Linq;
using Newtonsoft.Json;
using Oathx.Core;
using Oathx.Entity;
using Oathx.Widget;

/// <summary>Coordinates the local mail reference without network or inventory services.</summary>
public class MailSystem : RuntimeSystem
{
    /// <summary>Open the inbox and bind actions after the asynchronous page load.</summary>
    /// <returns>True when opening was requested.</returns>
    public override bool OnActive()
    {
        if (!IsActive())
            return false;

        UISystem.GetSingleton().OpenWidget<UIMail>((widget) => {
            if (widget)
            {
                var vm = widget.vm;
                if (!vm)
                    return;

                var entity = XEntityManager.GetSingleton().QueryEntity<MailEntity>();
                if (!entity)
                    return;

                if (!entity.initialized)
                {
                    string example = widget.GetExample();
                    var messages = string.IsNullOrEmpty(example) ? new MailMessage[0]
                        : JsonConvert.DeserializeObject<MailMessage[]>(example);
                    if (messages != null && messages.Length > 0)
                    {
                        long offset = DateTimeOffset.UtcNow.ToUnixTimeSeconds() - messages.Max(item => item.sentAt);
                        foreach (var message in messages)
                        {
                            message.sentAt += offset;
                            message.expiresAt += offset;
                        }
                    }

                    if (!entity.ReplaceInbox(messages))
                        throw new InvalidOperationException("Invalid local mail example.");
                }

                vm.CloseClick = (sender) => Close();
                vm.MessageClick = (sender, index) => Select(index);
                vm.ClaimClick = (sender) => Claim();
                vm.DeleteClick = (sender) => Delete();
                vm.ClaimAllClick = (sender) => ClaimAll();
                vm.DeleteReadClick = (sender) => DeleteRead();
                vm.MessageTemplate = false;
                vm.RewardTemplate = false;

                Refresh();
            }
        });

        return true;
    }

    /// <summary>Release the page through the shared system-level close API.</summary>
    public override void OnDetive()
    {
        UnsubscribeAll();

        System.Type[] widgets = new System.Type[] {
            typeof(UIMail)
        };

        UISystem.GetSingleton().CloseWidget(widgets, immediate: false);
    }

    /// <summary>Update list and detail snapshots from current entity data.</summary>
    /// <returns>True when the active view was updated.</returns>
    public bool Refresh()
    {
        if (!IsActive() || !UISystem.GetSingleton().TryGetWidget<UIMail>(out var widget))
            return false;

        var vm = widget.vm;
        if (!vm)
            return false;

        var entity = XEntityManager.GetSingleton().QueryEntity<MailEntity>();
        if (!entity)
            return false;

        long now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        var messages = entity.GetMessages(now);
        if (entity.GetSelected(now) == null && messages.Count > 0)
            entity.Select(messages[0].id, now);

        messages = entity.GetMessages(now);
        var selected = entity.GetSelected(now);
        vm.Messages = messages.Select(item => new VMMailEntry {
            mailId = item.id,
            Title = item.title,
            SentAt = DateTimeOffset.FromUnixTimeSeconds(item.sentAt).ToString("yyyy/MM/dd", CultureInfo.InvariantCulture),
            Selected = item.id == entity.selectedId,
            Unselected = item.id != entity.selectedId && !(item.claimed || item.read && item.rewards.Count == 0),
            Received = item.id != entity.selectedId && (item.claimed || item.read && item.rewards.Count == 0),
            Unread = !item.read,
            HasAttachment = item.rewards.Count > 0,
            Claimed = item.claimed,
            Pending = !item.claimed && item.rewards.Count > 0
        }).ToList();
        vm.Total = messages.Count.ToString(CultureInfo.InvariantCulture);
        vm.Unread = messages.Count(item => !item.read).ToString(CultureInfo.InvariantCulture);
        vm.EmptyVisible = messages.Count == 0;
        vm.EnvelopeState = messages.Count > 0 ? "EnvelopeOpen" : "EnvelopeClose";
        vm.DetailVisible = selected != null;
        vm.CanClaimAll = messages.Any(item => entity.CheckClaim(item.id, now) == MailResult.Success);
        vm.CanDeleteRead = messages.Any(item => entity.CheckDelete(item.id) == MailResult.Success);
        vm.Title = selected == null ? string.Empty : selected.title;
        vm.Body = selected == null ? string.Empty : selected.body;
        vm.SentAt = selected == null ? string.Empty : DateTimeOffset.FromUnixTimeSeconds(selected.sentAt).ToString("yyyy/MM/dd", CultureInfo.InvariantCulture);
        vm.Expiry = selected == null ? string.Empty : Math.Ceiling((selected.expiresAt - now) / 86400d).ToString(CultureInfo.InvariantCulture);
        vm.ClaimVisible = selected != null && entity.CheckClaim(selected.id, now) == MailResult.Success;
        vm.DeleteVisible = selected != null && entity.CheckDelete(selected.id) == MailResult.Success;
        vm.Rewards = (selected == null ? new System.Collections.Generic.List<MailReward>() : selected.rewards)
            .Select(item => new VMRewardEntry {
                Item = new VMItemSlot {
                    Text = item.count.ToString(CultureInfo.InvariantCulture),
                    Icon = item.icon,
                    IconVisible = true
                },
                Claimed = selected.claimed
            }).ToList();

        return true;
    }

    /// <summary>Open a displayed record by its stable identifier.</summary>
    /// <param name="index">Clicked view index.</param>
    /// <returns>True when the record was selected and rendered.</returns>
    public bool Select(int index)
    {
        if (!IsActive() || !UISystem.GetSingleton().TryGetWidget<UIMail>(out var widget))
            return false;

        var vm = widget.vm;
        if (!vm)
            return false;

        var entity = XEntityManager.GetSingleton().QueryEntity<MailEntity>();
        if (!entity)
            return false;

        if (vm.Messages == null || index < 0 || index >= vm.Messages.Count)
            return false;

        return entity.Select(vm.Messages[index].mailId, DateTimeOffset.UtcNow.ToUnixTimeSeconds()) && Refresh();
    }

    /// <summary>Record the selected attachment claim and refresh the current state.</summary>
    /// <returns>True when a new receipt was recorded.</returns>
    public bool Claim()
    {
        var entity = XEntityManager.GetSingleton().QueryEntity<MailEntity>();
        if (!entity || !IsActive())
            return false;

        var result = entity.Claim(entity.selectedId, DateTimeOffset.UtcNow.ToUnixTimeSeconds());
        Refresh();

        return result == MailResult.Success;
    }

    /// <summary>Delete the selected eligible record.</summary>
    /// <returns>True when the record was deleted.</returns>
    public bool Delete()
    {
        var entity = XEntityManager.GetSingleton().QueryEntity<MailEntity>();
        if (!entity || !IsActive())
            return false;

        var result = entity.Delete(entity.selectedId);
        Refresh();

        return result == MailResult.Success;
    }

    /// <summary>Record all available local claims without granting items.</summary>
    /// <returns>True when at least one new receipt was recorded.</returns>
    public bool ClaimAll()
    {
        var entity = XEntityManager.GetSingleton().QueryEntity<MailEntity>();
        if (!entity || !IsActive())
            return false;

        int count = entity.ClaimAll(DateTimeOffset.UtcNow.ToUnixTimeSeconds());
        Refresh();

        return count > 0;
    }

    /// <summary>Delete only read records with no outstanding attachments.</summary>
    /// <returns>True when at least one record was deleted.</returns>
    public bool DeleteRead()
    {
        var entity = XEntityManager.GetSingleton().QueryEntity<MailEntity>();
        if (!entity || !IsActive())
            return false;

        int count = entity.DeleteRead();
        Refresh();

        return count > 0;
    }

    /// <summary>Request closure through the lifecycle coordinator.</summary>
    /// <returns>True when the close request was dispatched.</returns>
    private bool Close()
    {
        return XPluginUtility.PostEvent(new SystemDetive { type = typeof(MailSystem) });
    }
}

using System;
using System.Collections;
using Oathx.Widget;
using UnityEngine;

/// <summary>Displays a host-owned inbox through standard Widget bindings.</summary>
[Config("Assets/Data/Widgets/Mail/Mail.prefab", WidgetLayer.topmost, cacheWidget: false)]
public class UIMail : UIWidget<VMMail>
{
    /// <summary>Optional example inbox, used only before a product supplies data.</summary>
    [SerializeField]
    private TextAsset example;

    /// <summary>Original page entrance and closing states.</summary>
    [SerializeField]
    private Animator entrance;

    /// <summary>Interaction gate while the page closes.</summary>
    [SerializeField]
    private CanvasGroup interaction;

    /// <summary>Restore the original entrance when activated.</summary>
    /// <returns>True when the base widget activated.</returns>
    public override bool Active()
    {
        bool active = base.Active();
        if (active && entrance && interaction)
        {
            interaction.interactable = true;
            entrance.Play("Open", 0, 0f);
        }

        return active;
    }

    /// <summary>Complete framework closure after the source exit animation.</summary>
    /// <param name="complete">Framework completion callback.</param>
    public override void Close(Action complete)
    {
        StartCoroutine(PlayClose(complete));
    }

    /// <summary>Read the optional local example without owning business data.</summary>
    /// <returns>The example JSON or an empty string.</returns>
    public string GetExample()
    {
        return example ? example.text : string.Empty;
    }

    /// <summary>Play the original closing state without allowing another action.</summary>
    /// <param name="complete">Framework completion callback.</param>
    /// <returns>The source-duration close sequence.</returns>
    private IEnumerator PlayClose(Action complete)
    {
        if (interaction)
            interaction.interactable = false;

        if (entrance)
        {
            entrance.Play("Close", 0, 0f);
            yield return new WaitForSecondsRealtime(0.27f);
        }

        complete?.Invoke();
    }
}

